<link rel="stylesheet" href="<?=asset('css/support-receipts.css')?>">
<main class="write-main"><h1>Support receipts</h1><p>Private individual and company/institution support records. Online receipts use verified live payment evidence. Bank transfers require a matching receiving statement; no money is moved by this page.</p>
<?php foreach(flashes()as$f):?><p class="notice"><?=e($f['message'])?></p><?php endforeach;?><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<div class="support-receipt-list"><?php foreach($rows as$r):$state=support_receipt_state($r);?><article><h2><?=e($r['identity']['name'])?></h2><p><?=e(support_purpose($r['identity']).' · '.$r['currency'].' '.$r['amount'])?></p><p><?=e($r['reference'])?> · <?=$state['paid']?'Verified receipt':e(ucfirst($state['state']))?></p><?php if($r['identity']['email']!==''):?><p>Accounts contact: <?=e($r['identity']['email'])?></p><?php endif;?><a href="<?=e(support_receipt_url($r))?>" target="_blank" rel="noopener noreferrer">Open private record / receipt</a>
<?php if(!empty($r['identity']['public_share'])&&empty($r['public_hidden_at'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="hide"><input type="hidden" name="receipt_id" value="<?=e($r['id'])?>"><p>Public display after verification: <?=e($r['identity']['public_name']??'Anonymous')?></p><button class="wbtn">Remove public acknowledgement</button></form><?php endif;?>
<?php if(!empty($state['can_verify'])):?><details><summary>Verify against the receiving statement</summary><form method="post"><?=csrf_field()?><input type="hidden" name="receipt_id" value="<?=e($r['id'])?>"><label class="support-field">Receiving statement transaction reference<input name="transaction" maxlength="180" required></label><label class="support-field">Actual amount received<input name="verified_amount" inputmode="decimal" required></label><label class="support-field">Actual currency<input name="verified_currency" maxlength="3" required></label><label><input type="checkbox" name="bank_ack" value="1" required>I verified the receiving account statement, payer, reference, amount and currency. A submitted record or screenshot alone is not evidence.</label><button class="wbtn primary">Confirm received payment</button></form></details><?php endif;?><?php if(empty($r['voided_at'])):?><details><summary>Void this receipt record</summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="void"><input type="hidden" name="receipt_id" value="<?=e($r['id'])?>"><label class="support-field">Reason<textarea name="void_reason" maxlength="1000" required></textarea></label><label><input type="checkbox" name="void_ack" value="1" required>Void the receipt only. This does not refund the payment or free the statement transaction for reuse.</label><button class="wbtn">Void receipt record</button></form></details><?php endif;?></article><?php endforeach;?></div><?php if(!$rows):?><p>No receipt details on this page. Existing payments are not assigned invented payer names.</p><?php endif;?><nav aria-label="Receipt pages"><?php if($receiptPage>1):?><a href="<?=url('/write/contribution-receipts?page='.($receiptPage-1))?>">Previous</a><?php endif;?> <?php if($receiptPage*20<$receiptTotal):?><a href="<?=url('/write/contribution-receipts?page='.($receiptPage+1))?>">Next</a><?php endif;?></nav></main>
